#include <stdlib.h>
#include <string.h>
#include <float.h>
typedef double cost;
/* returns 0 on success; x[i]=col for row i */
int lapjv(int n, const cost *c, int *x, int *y_out){
  int *y=y_out; cost *v=malloc(n*sizeof(cost));
  int *freer=malloc(n*sizeof(int)), *collist=malloc(n*sizeof(int)), *matches=calloc(n,sizeof(int)), *pred=malloc(n*sizeof(int));
  cost *d=malloc(n*sizeof(cost));
  int i,j,j1,j2=0,i0,k,numfree=0,f,loopcnt,prvnumfree,last=0,low,up,endofpath=0;
  cost min=0,h,umin,usubmin,v2;
  for(i=0;i<n;i++) x[i]=-1;
  /* column reduction */
  for(j=n-1;j>=0;j--){
    min=c[j]; int imin=0;
    for(i=1;i<n;i++) if(c[(long)i*n+j]<min){min=c[(long)i*n+j];imin=i;}
    v[j]=min;
    if(++matches[imin]==1){x[imin]=j;y[j]=imin;} else y[j]=-1;
  }
  /* reduction transfer */
  for(i=0;i<n;i++){
    if(matches[i]==0) freer[numfree++]=i;
    else if(matches[i]==1){
      j1=x[i]; const cost*ci=c+(long)i*n; min=DBL_MAX;
      for(j=0;j<n;j++) if(j!=j1){ h=ci[j]-v[j]; if(h<min) min=h; }
      v[j1]-=min;
    }
  }
  /* augmenting row reduction */
  loopcnt=0;
  do{
    loopcnt++;
    k=0; prvnumfree=numfree; numfree=0;
    while(k<prvnumfree){
      i=freer[k++]; const cost*ci=c+(long)i*n;
      umin=ci[0]-v[0]; j1=0; usubmin=DBL_MAX;
      for(j=1;j<n;j++){
        h=ci[j]-v[j];
        if(h<usubmin){
          if(h>=umin){usubmin=h;j2=j;}
          else{usubmin=umin;umin=h;j2=j1;j1=j;}
        }
      }
      i0=y[j1];
      if(umin<usubmin) v[j1]=v[j1]-(usubmin-umin);
      else if(i0>=0){j1=j2;i0=y[j2];}
      x[i]=j1;y[j1]=i;
      if(i0>=0){
        if(umin<usubmin) freer[--k]=i0;
        else freer[numfree++]=i0;
      }
    }
  }while(loopcnt<2);
  /* augment */
  for(f=0;f<numfree;f++){
    int freerow=freer[f]; const cost*cf=c+(long)freerow*n;
    for(j=0;j<n;j++){d[j]=cf[j]-v[j];pred[j]=freerow;collist[j]=j;}
    low=0;up=0;
    int unassignedfound=0;
    do{
      if(up==low){
        last=low-1;
        min=d[collist[up++]];
        for(k=up;k<n;k++){
          j=collist[k]; h=d[j];
          if(h<=min){
            if(h<min){up=low;min=h;}
            collist[k]=collist[up]; collist[up++]=j;
          }
        }
        for(k=low;k<up;k++) if(y[collist[k]]<0){endofpath=collist[k];unassignedfound=1;break;}
      }
      if(!unassignedfound){
        j1=collist[low++]; i=y[j1]; const cost*ci=c+(long)i*n;
        h=ci[j1]-v[j1]-min;
        for(k=up;k<n;k++){
          j=collist[k]; v2=ci[j]-v[j]-h;
          if(v2<d[j]){
            pred[j]=i;
            if(v2==min){
              if(y[j]<0){endofpath=j;unassignedfound=1;break;}
              else{collist[k]=collist[up];collist[up++]=j;}
            }
            d[j]=v2;
          }
        }
      }
    }while(!unassignedfound);
    for(k=0;k<=last;k++){j1=collist[k];v[j1]=v[j1]+d[j1]-min;}
    do{
      i=pred[endofpath]; y[endofpath]=i; j1=endofpath; endofpath=x[i]; x[i]=j1;
    }while(i!=freerow);
  }
  free(v);free(freer);free(collist);free(matches);free(pred);free(d);
  return 0;
}
