#include <stdlib.h>
#include <string.h>
#include <math.h>
static void swapd(double*a,int*ia,int i,int j){double t=a[i];a[i]=a[j];a[j]=t;int s=ia[i];ia[i]=ia[j];ia[j]=s;}
/* select k smallest of row (vals, idx), puts them in first k */
static void qsel(double*a,int*ia,int lo,int hi,int k){
  while(hi>lo){
    int mid=(lo+hi)>>1;
    if(a[mid]<a[lo])swapd(a,ia,mid,lo);
    if(a[hi]<a[lo])swapd(a,ia,hi,lo);
    if(a[hi]<a[mid])swapd(a,ia,hi,mid);
    double p=a[mid]; int i=lo,j=hi;
    while(i<=j){while(a[i]<p)i++;while(a[j]>p)j--;if(i<=j){swapd(a,ia,i,j);i++;j--;}}
    if(k<=j)hi=j; else if(k>=i)lo=i; else return;
  }
}
/* heap */
typedef struct{double d;int j;}HE;
static void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;while(1){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}if(n>0)h[i]=last;return top;}

/* returns 0 ok, 1 infeasible sparse, 2 not optimal on dense */
int sap(int n,const double*C,int k,int*x){
  if(k>n)k=n;
  long nnz=(long)n*k;
  int *ci=malloc(nnz*sizeof(int)); double*cv=malloc(nnz*sizeof(double));
  double*tmp=malloc(n*sizeof(double)); int*ti=malloc(n*sizeof(int));
  for(int i=0;i<n;i++){
    const double*r=C+(long)i*n;
    memcpy(tmp,r,n*sizeof(double)); for(int j=0;j<n;j++)ti[j]=j;
    if(k<n) qsel(tmp,ti,0,n-1,k-1);
    memcpy(ci+(long)i*k,ti,k*sizeof(int)); memcpy(cv+(long)i*k,tmp,k*sizeof(double));
  }
  double*u=calloc(n,sizeof(double)),*v=calloc(n,sizeof(double)),*sh=malloc(n*sizeof(double));
  int*y=malloc(n*sizeof(int)),*pred=malloc(n*sizeof(int)),*done=calloc(n,sizeof(int));
  int*SC=malloc(n*sizeof(int)),*SR=malloc(n*sizeof(int)),*touched=malloc(n*sizeof(int));
  HE*h=malloc((nnz+n)*sizeof(HE));
  for(int j=0;j<n;j++){y[j]=-1;sh[j]=INFINITY;}
  for(int i=0;i<n;i++)x[i]=-1;
  int ret=0;
  /* greedy init: assign row to its min reduced-cost column if free */
  for(int i=0;i<n;i++){
    int*cc=ci+(long)i*k;double*vv=cv+(long)i*k;int bj=-1;double bm=INFINITY;
    for(int t=0;t<k;t++)if(vv[t]<bm){bm=vv[t];bj=cc[t];}
    u[i]=bm; /* reduced costs >=0 with v=0 on row i */
    if(y[bj]<0){y[bj]=i;x[i]=bj;}
  }
  /* note: u[i]=min row cost keeps reduced>=0 on sparse edges; matched edges have 0 */
  for(int root=0;root<n;root++){
    if(x[root]>=0)continue;
    int nsc=0,nsr=0,nt=0,hs=0; int i=root; double minv=0; int sink=-1;
    while(1){
      SR[nsr++]=i;
      int*cc=ci+(long)i*k;double*vv=cv+(long)i*k;
      for(int t=0;t<k;t++){int j=cc[t];if(done[j])continue;
        double r=minv+vv[t]-u[i]-v[j];
        if(r<sh[j]){if(sh[j]==INFINITY)touched[nt++]=j;sh[j]=r;pred[j]=i;hpush(h,&hs,r,j);}
      }
      int j=-1;
      while(hs>0){HE e=hpop(h,&hs);if(done[e.j]||e.d>sh[e.j])continue;j=e.j;minv=e.d;break;}
      if(j<0){ret=1;break;}
      done[j]=1;SC[nsc++]=j;
      if(y[j]<0){sink=j;break;}
      i=y[j];
    }
    if(ret)break;
    u[root]+=minv;
    for(int t=1;t<nsr;t++){int r=SR[t];u[r]+=minv-sh[x[r]];}
    for(int t=0;t<nsc;t++){int j=SC[t];if(j!=sink||1)v[j]-=minv-sh[j];}
    /* augment */
    int j=sink;
    while(1){int r=pred[j];y[j]=r;int nj=x[r];x[r]=j;if(r==root)break;j=nj;}
    for(int t=0;t<nt;t++){sh[touched[t]]=INFINITY;done[touched[t]]=0;}
  }
  if(!ret){
    /* dense dual feasibility check */
    for(int i=0;i<n&&!ret;i++){const double*r=C+(long)i*n;double ui=u[i];
      for(int j=0;j<n;j++)if(r[j]-ui-v[j]<-1e-12){ret=2;break;}}
  }
  free(ci);free(cv);free(tmp);free(ti);free(u);free(v);free(sh);free(y);free(pred);free(done);free(SC);free(SR);free(touched);free(h);
  return ret;
}
