    int mid=(lo+hi)>>1;
    if(a[mid]<a[lo])swapd(a,ia,mid,lo);
    if(a[hi]<a[lo])swapd(a,ia,hi,lo);
    if(a[hi]<a[mid])swapd(a,ia,hi,mid);
    double p=a[mid]; int i=lo,j=hi;
    while(i<=j){while(a[i]<p)i++;while(a[j]>p)j--;if(i<=j){swapd(a,ia,i,j);i++;j--;}}
    if(k<=j)hi=j; else if(k>=i)lo=i; else return;
  }
}
typedef struct{double d;int j;}HE;
static void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;while(1){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}if(n>0)h[i]=last;return top;}

int sap(int n,const double*C,int k,int*x){
  if(k>n)k=n;
  int **ci=malloc(n*sizeof(int*)); int*deg=malloc(n*sizeof(int)),*cap=malloc(n*sizeof(int));
  double*tmp=malloc(n*sizeof(double)); int*ti=malloc(n*sizeof(int));
  for(int i=0;i<n;i++){
    const double*r=C+(long)i*n;
    memcpy(tmp,r,n*sizeof(double)); for(int j=0;j<n;j++)ti[j]=j;
    if(k<n) qsel(tmp,ti,0,n-1,k-1);
    cap[i]=2*k+8; deg[i]=k; ci[i]=malloc(cap[i]*sizeof(int));
    memcpy(ci[i],ti,k*sizeof(int));
  }
  double*u=calloc(n,sizeof(double)),*v=calloc(n,sizeof(double)),*sh=malloc(n*sizeof(double));
  int*y=malloc(n*sizeof(int)),*pred=malloc(n*sizeof(int)),*done=calloc(n,sizeof(int));
  int*SC=malloc(n*sizeof(int)),*SR=malloc(n*sizeof(int)),*touched=malloc(n*sizeof(int));
  int*freer=malloc(n*sizeof(int)); int nfree=0;
  int hcap=n*k+n; HE*h=malloc(hcap*sizeof(HE));
  for(int j=0;j<n;j++){y[j]=-1;sh[j]=INFINITY;}
  for(int i=0;i<n;i++)x[i]=-1;
  int ret=0;
  for(int i=0;i<n;i++){
    const double*r=C+(long)i*n;int*cc=ci[i];int bj=-1;double bm=INFINITY;
    for(int t=0;t<k;t++){double c=r[cc[t]];if(c<bm){bm=c;bj=cc[t];}}
    u[i]=bm;
    if(y[bj]<0){y[bj]=i;x[i]=bj;} else freer[nfree++]=i;
  }
  for(int round=0;round<50;round++){
    for(int f=0;f<nfree;f++){
      int root=freer[f];
      int nsc=0,nsr=0,nt=0,hs=0; int i=root; double minv=0; int sink=-1;
      while(1){
        SR[nsr++]=i;
        const double*r=C+(long)i*n; int*cc=ci[i]; int dg=deg[i]; double ui=u[i];
        for(int t=0;t<dg;t++){int j=cc[t];if(done[j])continue;
          double rc=minv+r[j]-ui-v[j];
          if(rc<sh[j]){if(sh[j]==INFINITY)touched[nt++]=j;sh[j]=rc;pred[j]=i;
            if(hs>=hcap){hcap*=2;h=realloc(h,hcap*sizeof(HE));}
            hpush(h,&hs,rc,j);}
        }
        int j=-1;
        while(hs>0){HE e=hpop(h,&hs);if(done[e.j]||e.d>sh[e.j])continue;j=e.j;minv=e.d;break;}
        if(j<0){ret=1;break;}
        done[j]=1;SC[nsc++]=j;
        if(y[j]<0){sink=j;break;}
        i=y[j];
      }
      if(ret)goto end;
      u[root]+=minv;
      for(int t=1;t<nsr;t++){int r=SR[t];u[r]+=minv-sh[x[r]];}
      for(int t=0;t<nsc;t++){int j=SC[t];v[j]-=minv-sh[j];}
      int j=sink;
      while(1){int r=pred[j];y[j]=r;int nj=x[r];x[r]=j;if(r==root)break;j=nj;}
      for(int t=0;t<nt;t++){sh[touched[t]]=INFINITY;done[touched[t]]=0;}
    }
    /* dense check + repair */
    nfree=0;
    for(int i=0;i<n;i++){const double*r=C+(long)i*n;double ui=u[i];int viol=0;double mn=INFINITY;
      for(int j=0;j<n;j++){double rc=r[j]-ui-v[j];
        if(rc<-1e-13){viol=1;
          if(deg[i]>=cap[i]){cap[i]*=2;ci[i]=realloc(ci[i],cap[i]*sizeof(int));}
          ci[i][deg[i]++]=j; if(rc<mn)mn=rc;}}
      if(viol){u[i]+=mn; y[x[i]]=-1; x[i]=-1; freer[nfree++]=i;}
    }
    if(nfree==0){ret=0;goto end;}
  }
  ret=2;
end:
  for(int i=0;i<n;i++)free(ci[i]);
  free(ci);free(deg);free(cap);free(tmp);free(ti);free(u);free(v);free(sh);free(y);free(pred);free(done);free(SC);free(SR);free(touched);free(h);free(freer);
  return ret;
}
