    const unsigned char *in; unsigned char *out;
    size_t off, len;            /* off multiple of 64 */
    const unsigned int *key; const unsigned int *nonce;
    const unsigned char *pkey;  /* r || 0 */
    unsigned char t1[16], t2[16];
} job_t;

#define SUB 16384
static void *worker(void *arg) {
    job_t *j = (job_t*)arg;
    size_t csz = Poly1305_ctx_size();
    void *ctx = aligned_alloc(64, (csz + 63) & ~63UL);
    void *ctx2 = aligned_alloc(64, (csz + 63) & ~63UL);
