    unsigned int key[8], nonce[3];
    memcpy(key, kb.buf, 32); memcpy(nonce, nb.buf, 12);
    size_t len = pb.len;
    unsigned char blk[64] = {0};
    unsigned int c0[4] = {0, nonce[0], nonce[1], nonce[2]};
