    if (nth < 1) nth = 1;
    if ((size_t)nth > nblk) nth = nblk ? (int)nblk : 1;
    job_t jobs[64]; pthread_t th[64];
    if (nth > 64) nth = 64;
    size_t per = nblk / nth, rem = nblk % nth, b = 0;
    for (int i = 0; i < nth; i++) {
        size_t cnt = per + ((size_t)i < rem);
        size_t off = b * 64, end = (b + cnt) * 64; if (end > len) end = len;
        jobs[i].in = (const unsigned char*)pb.buf + off; jobs[i].out = out + off;
        jobs[i].off = off; jobs[i].len = end - off;
        jobs[i].key = key; jobs[i].nonce = nonce; jobs[i].pkey = pkey;
        b += cnt;
    }
    Py_BEGIN_ALLOW_THREADS
    for (int i = 1; i < nth; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
    worker(&jobs[0]);
    for (int i = 1; i < nth; i++) pthread_join(th[i], NULL);
    Py_END_ALLOW_THREADS
    PyObject *lst = PyList_New(nth);
    for (int i = 0; i < nth; i++) {
        PyObject *t = Py_BuildValue("(y#y#n)", jobs[i].t1, (Py_ssize_t)16, jobs[i].t2, (Py_ssize_t)16, (Py_ssize_t)jobs[i].len);
