    }
    PyObject *res = Py_BuildValue("(NNy#y#)", ct, lst, blk, (Py_ssize_t)16, blk + 16, (Py_ssize_t)16);
    PyBuffer_Release(&kb); PyBuffer_Release(&nb); PyBuffer_Release(&pb);
    return res;
}

static PyMethodDef M[] = {{"enc", enc, METH_VARARGS, ""}, {NULL}};
static struct PyModuleDef mod = {PyModuleDef_HEAD_INIT, "chacha_fast", NULL, -1, M};
PyMODINIT_FUNC PyInit_chacha_fast(void) { return PyModule_Create(&mod); }
