import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from chacha_fast import enc

P = (1 << 130) - 5
M128 = (1 << 128) - 1
NTH = os.cpu_count() or 4


def _poly_blocks(data, r):
    h = 0
    for i in range(0, len(data), 16):
        blk = data[i:i + 16]
        h = ((h + int.from_bytes(blk, "little") + (1 << (8 * len(blk)))) * r) % P
    return h


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]; nonce = problem["nonce"]
        pt = problem["plaintext"]; aad = problem.get("associated_data") or b""
        if len(key) != 32 or len(nonce) != 12:
            raise ValueError("bad key/nonce")
        nth = NTH if len(pt) >= (1 << 20) else 1
        ct, parts, rb, sb = enc(key, nonce, pt, nth)
        r = int.from_bytes(rb, "little") & 0x0ffffffc0ffffffc0ffffffc0fffffff
        s = int.from_bytes(sb, "little")
        # aad padded
        a = aad + b"\0" * ((-len(aad)) % 16)
        H = 0
        if a:
            for i in range(0, len(a), 16):
                H = ((H + int.from_bytes(a[i:i+16], "little") + (1 << 128)) * r) % P
        for t1b, t2b, ln in parts:
            if ln == 0:
                continue
            t1 = int.from_bytes(t1b, "little"); t2 = int.from_bytes(t2b, "little")
            h = None
            for k in range(4):
                c = t1 + (k << 128)
                if c < P and ((c * r) % P) & M128 == t2:
                    h = c; break
            nb = (ln + 15) // 16
            H = (H * pow(r, nb, P) + h) % P
        lenblk = len(aad).to_bytes(8, "little") + len(pt).to_bytes(8, "little")
        H = ((H + int.from_bytes(lenblk, "little") + (1 << 128)) * r) % P
        tag = ((H + s) & M128).to_bytes(16, "little")
        return {"ciphertext": ct, "tag": tag}
