import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from chacha_fast import enc

NTH = os.cpu_count() or 4
BIG = 1 << 20


class Solver:
    def __init__(self):
        self._pool = []

    def _take(self, n):
        pool = self._pool
        for i in range(len(pool)):
            # refs: pool list + getrefcount arg -> nobody else holds it
            if sys.getrefcount(pool[i]) == 2 and len(pool[i]) == n:
                return pool.pop(i)
        return None

    def solve(self, problem, **kwargs):
        key = problem["key"]; nonce = problem["nonce"]
        pt = problem["plaintext"]; aad = problem.get("associated_data") or b""
        if len(key) != 32 or len(nonce) != 12:
            raise ValueError("bad key/nonce")
        n = len(pt)
        if n >= BIG:
            reuse = self._take(n)
            ct, tag = enc(key, nonce, pt, aad, NTH, reuse)
            del reuse
            pool = self._pool
            pool.append(ct)
            if len(pool) > 3:
                pool.pop(0)
        else:
            ct, tag = enc(key, nonce, pt, aad, 1 if n < 65536 else NTH)
        return {"ciphertext": ct, "tag": tag}
