#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <pthread.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/core_names.h>
#include <openssl/params.h>

typedef struct {
    const unsigned char *key, *nonce, *in;
    unsigned char *out;
    size_t off, len;      /* off multiple of 64 */
    unsigned char polykey[32]; /* r || 0 */
    unsigned char t1[16], t2[16];
    int err;
} job_t;

static EVP_MAC *g_mac;
static const EVP_CIPHER *g_cipher;

static void *worker(void *arg) {
    job_t *j = (job_t*)arg;
    j->err = 1;
    unsigned char iv[16];
    uint32_t ctr = (uint32_t)(1 + j->off / 64);
    iv[0]=ctr; iv[1]=ctr>>8; iv[2]=ctr>>16; iv[3]=ctr>>24;
    memcpy(iv+4, j->nonce, 12);
    EVP_CIPHER_CTX *c = EVP_CIPHER_CTX_new();
    if (!c) return NULL;
    if (EVP_EncryptInit_ex(c, g_cipher, NULL, j->key, iv) != 1) { EVP_CIPHER_CTX_free(c); return NULL; }
    EVP_MAC_CTX *m = EVP_MAC_CTX_new(g_mac);
    if (!m || EVP_MAC_init(m, j->polykey, 32, NULL) != 1) { EVP_CIPHER_CTX_free(c); return NULL; }
    const size_t SB = 16384;
    size_t done = 0;
    while (done < j->len) {
        size_t n = j->len - done; if (n > SB) n = SB;
        int ol;
        EVP_EncryptUpdate(c, j->out + done, &ol, j->in + done, (int)n);
        EVP_MAC_update(m, j->out + done, n);
        done += n;
    }
    /* pad to 16 */
    size_t rem = j->len % 16;
    unsigned char zeros[16] = {0};
    if (rem) EVP_MAC_update(m, zeros, 16 - rem);
    EVP_MAC_CTX *m2 = EVP_MAC_CTX_dup(m);
    size_t tl;
    EVP_MAC_final(m, j->t1, &tl, 16);
    EVP_MAC_update(m2, zeros, 16);
    EVP_MAC_final(m2, j->t2, &tl, 16);
    EVP_MAC_CTX_free(m); EVP_MAC_CTX_free(m2);
    EVP_CIPHER_CTX_free(c);
    j->err = 0;
    return NULL;
}

#define MAXT 64
static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, rkey;
    int nthreads;
    if (!PyArg_ParseTuple(args, "y*y*y*y*i", &key, &nonce, &pt, &rkey, &nthreads)) return NULL;
    size_t len = pt.len;
    PyObject *out = PyBytes_FromStringAndSize(NULL, len);
    if (!out) goto fail;
    unsigned char *op = (unsigned char*)PyBytes_AS_STRING(out);
    if (nthreads < 1) nthreads = 1; if (nthreads > MAXT) nthreads = MAXT;
    size_t nblk = (len + 63) / 64;
    if ((size_t)nthreads > nblk) nthreads = nblk ? (int)nblk : 1;
    job_t jobs[MAXT]; pthread_t th[MAXT];
    size_t per = nblk / nthreads, extra = nblk % nthreads, b = 0;
    for (int i = 0; i < nthreads; i++) {
        size_t nb = per + ((size_t)i < extra);
        jobs[i].key = key.buf; jobs[i].nonce = nonce.buf;
        jobs[i].in = (const unsigned char*)pt.buf + b*64; jobs[i].out = op + b*64;
        jobs[i].off = b*64;
        size_t end = (b+nb)*64; if (end > len) end = len;
        jobs[i].len = end - b*64;
        memcpy(jobs[i].polykey, rkey.buf, 16); memset(jobs[i].polykey+16, 0, 16);
        b += nb;
    }
    Py_BEGIN_ALLOW_THREADS
    for (int i = 1; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
    worker(&jobs[0]);
    for (int i = 1; i < nthreads; i++) pthread_join(th[i], NULL);
    Py_END_ALLOW_THREADS
    PyObject *lst = PyList_New(nthreads);
    for (int i = 0; i < nthreads; i++) {
        if (jobs[i].err) { PyErr_SetString(PyExc_RuntimeError, "openssl failure"); Py_DECREF(lst); Py_DECREF(out); goto fail; }
        PyList_SET_ITEM(lst, i, Py_BuildValue("(y#y#n)", jobs[i].t1, (Py_ssize_t)16, jobs[i].t2, (Py_ssize_t)16, (Py_ssize_t)((jobs[i].len+15)/16)));
    }
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&rkey);
    return Py_BuildValue("(NN)", out, lst);
fail:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&rkey);
    return NULL;
}

static PyMethodDef M[] = {{"encrypt", encrypt, METH_VARARGS, ""}, {NULL}};
static struct PyModuleDef mod = {PyModuleDef_HEAD_INIT, "fastcc", NULL, -1, M};
PyMODINIT_FUNC PyInit_fastcc(void) {
    g_mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    g_cipher = EVP_CIPHER_fetch(NULL, "ChaCha20", NULL);
    if (!g_mac || !g_cipher) { PyErr_SetString(PyExc_ImportError, "openssl fetch failed"); return NULL; }
    return PyModule_Create(&mod);
}
