#include <sys/mman.h>
#include <mach/vm_statistics.h>
#include <openssl/evp.h>

#define CHUNK 16384
#define MAXSEG 256
#define MAXT 64

static EVP_MAC *g_mac;
static const EVP_CIPHER *g_cipher;

typedef struct { size_t off, len; unsigned char t[32]; int err; } seg_t;

static struct {
    const unsigned char *key, *nonce, *in; unsigned char *out;
    unsigned char polykey[32];
    seg_t seg[MAXSEG]; int nseg;
    _Atomic int next; _Atomic int remaining;
    long gen;
} W;
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_start = PTHREAD_COND_INITIALIZER, cv_done = PTHREAD_COND_INITIALIZER;
static int nworkers = 0;

static void do_seg(seg_t *s) {
    s->err = 1;
    unsigned char iv[16];
    uint32_t ctr = (uint32_t)(1 + s->off / 64);
    iv[0]=ctr; iv[1]=ctr>>8; iv[2]=ctr>>16; iv[3]=ctr>>24;
    memcpy(iv+4, W.nonce, 12);
    EVP_CIPHER_CTX *c = EVP_CIPHER_CTX_new();
    if (!c) return;
    if (EVP_EncryptInit_ex(c, g_cipher, NULL, W.key, iv) != 1) { EVP_CIPHER_CTX_free(c); return; }
    EVP_MAC_CTX *m = EVP_MAC_CTX_new(g_mac);
    if (!m || EVP_MAC_init(m, W.polykey, 32, NULL) != 1) { EVP_CIPHER_CTX_free(c); if (m) EVP_MAC_CTX_free(m); return; }
    const unsigned char *in = W.in + s->off; unsigned char *out = W.out + s->off;
    size_t done = 0;
    while (done < s->len) {
        size_t n = s->len - done; if (n > CHUNK) n = CHUNK;
        int ol;
        EVP_EncryptUpdate(c, out + done, &ol, in + done, (int)n);
        EVP_MAC_update(m, out + done, n);
        done += n;
    }
    unsigned char zeros[16] = {0};
    size_t rem = s->len % 16;
    if (rem) EVP_MAC_update(m, zeros, 16 - rem);
    EVP_MAC_CTX *m2 = EVP_MAC_CTX_dup(m);
    size_t tl;
    EVP_MAC_final(m, s->t, &tl, 16);
    EVP_MAC_update(m2, zeros, 16);
    EVP_MAC_final(m2, s->t + 16, &tl, 16);
    EVP_MAC_CTX_free(m); EVP_MAC_CTX_free(m2);
    EVP_CIPHER_CTX_free(c);
    s->err = 0;
}

static void run_segs(void) {
    for (;;) {
        int i = atomic_fetch_add(&W.next, 1);
        if (i >= W.nseg) break;
        do_seg(&W.seg[i]);
        if (atomic_fetch_sub(&W.remaining, 1) == 1) {
            pthread_mutex_lock(&mu); pthread_cond_broadcast(&cv_done); pthread_mutex_unlock(&mu);
        }
    }
}

static void *worker(void *arg) {
    long seen = 0;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (W.gen == seen) pthread_cond_wait(&cv_start, &mu);
        seen = W.gen;
        pthread_mutex_unlock(&mu);
        run_segs();
    }
    return NULL;
}

/* ---- buffer pool ---- */
#define POOLN 4
static void *pool_ptr[POOLN]; static size_t pool_cap[POOLN]; static int pool_n = 0;
static PyTypeObject FBType = {PyVarObject_HEAD_INIT(NULL, 0)};
static void fb_free(void *p) {
    void *base = (char*)p - 64;
    size_t cap = ((size_t*)base)[0];
    if (pool_n < POOLN) { pool_ptr[pool_n] = base; pool_cap[pool_n] = cap; pool_n++; return; }
    munmap(base, cap);
}
static void *raw_alloc(size_t need) {
    void *base = mmap(NULL, need, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANON, -1, 0);
    if (base == MAP_FAILED) return NULL;
    memset(base, 0, need);   /* prefault */
    ((size_t*)base)[0] = need;
    return base;
}
static PyObject *fb_new_sized(size_t n) {
    size_t need = 64 + offsetof(PyBytesObject, ob_sval) + n + 1;
    need = (need + (1<<21) - 1) & ~(size_t)((1<<21) - 1);
    void *base = NULL;
    for (int i = 0; i < pool_n; i++) if (pool_cap[i] >= need && pool_cap[i] <= need + (need>>2) + (4<<20)) {
        base = pool_ptr[i];
        pool_ptr[i] = pool_ptr[pool_n-1]; pool_cap[i] = pool_cap[pool_n-1]; pool_n--; break; }
    if (!base) {
        while (pool_n > 0) { pool_n--; munmap(pool_ptr[pool_n], pool_cap[pool_n]); }
        base = raw_alloc(need);
        if (!base) { PyErr_NoMemory(); return NULL; }
        /* keep a spare of same size ready */
        void *spare = raw_alloc(need);
        if (spare) { pool_ptr[pool_n] = spare; pool_cap[pool_n] = need; pool_n++; }
    }
    PyBytesObject *op = (PyBytesObject*)((char*)base + 64);
    PyObject_InitVar((PyVarObject*)op, &FBType, (Py_ssize_t)n);
_Pragma("clang diagnostic push") _Pragma("clang diagnostic ignored \"-Wdeprecated-declarations\"")
    op->ob_shash = -1;
_Pragma("clang diagnostic pop")
    op->ob_sval[n] = 0;
    return (PyObject*)op;
}

static void ensure_workers(int nt) {
    while (nworkers < nt - 1 && nworkers < MAXT) {
        pthread_t t; pthread_create(&t, NULL, worker, NULL); pthread_detach(t); nworkers++;
    }
}

static PyObject *fc_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, rkey;
    int nthreads, nseg;
    if (!PyArg_ParseTuple(args, "y*y*y*y*ii", &key, &nonce, &pt, &rkey, &nthreads, &nseg)) return NULL;
    PyObject *lst = NULL, *out = NULL;
    size_t len = pt.len;
    out = fb_new_sized(len);
    if (!out) goto fail;
    if (nthreads < 1) nthreads = 1;
    if (nseg < 1) nseg = 1;
    if (nseg > MAXSEG) nseg = MAXSEG;
    size_t nblk = (len + 63) / 64;
    if ((size_t)nseg > nblk) nseg = nblk ? (int)nblk : 1;
    W.key = key.buf; W.nonce = nonce.buf; W.in = pt.buf; W.out = (unsigned char*)PyBytes_AS_STRING(out);
    memcpy(W.polykey, rkey.buf, 16); memset(W.polykey + 16, 0, 16);
    size_t per = nblk / nseg, extra = nblk % nseg, b = 0;
    for (int i = 0; i < nseg; i++) {
        size_t nb = per + ((size_t)i < extra);
        size_t end = (b + nb) * 64; if (end > len) end = len;
        W.seg[i].off = b * 64; W.seg[i].len = end - b * 64;
        b += nb;
    }
    W.nseg = nseg;
    Py_BEGIN_ALLOW_THREADS
    ensure_workers(nthreads);
    atomic_store(&W.next, 0); atomic_store(&W.remaining, nseg);
    if (nthreads > 1) {
        pthread_mutex_lock(&mu); W.gen++; pthread_cond_broadcast(&cv_start); pthread_mutex_unlock(&mu);
    }
    run_segs();
    pthread_mutex_lock(&mu);
    while (atomic_load(&W.remaining) > 0) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);
    Py_END_ALLOW_THREADS
    lst = PyList_New(nseg);
    for (int i = 0; i < nseg; i++) {
        if (W.seg[i].err) { PyErr_SetString(PyExc_RuntimeError, "openssl failure"); Py_DECREF(lst); Py_DECREF(out); goto fail; }
        PyList_SET_ITEM(lst, i, Py_BuildValue("(y#n)", W.seg[i].t, (Py_ssize_t)32, (Py_ssize_t)((W.seg[i].len + 15) / 16)));
    }
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&rkey);
    return Py_BuildValue("(NN)", out, lst);
fail:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&rkey);
    return NULL;
}

static PyMethodDef M[] = {{"encrypt", fc_encrypt, METH_VARARGS, ""}, {NULL}};
static struct PyModuleDef mod = {PyModuleDef_HEAD_INIT, "fastcc", NULL, -1, M};
PyMODINIT_FUNC PyInit_fastcc(void) {
    g_mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    g_cipher = EVP_CIPHER_fetch(NULL, "ChaCha20", NULL);
    if (!g_mac || !g_cipher) { PyErr_SetString(PyExc_ImportError, "openssl fetch failed"); return NULL; }
    FBType.tp_name = "fastcc.FastBytes";
    FBType.tp_basicsize = PyBytes_Type.tp_basicsize;
    FBType.tp_itemsize = PyBytes_Type.tp_itemsize;
    FBType.tp_flags = Py_TPFLAGS_DEFAULT;
    FBType.tp_base = &PyBytes_Type;
    FBType.tp_free = fb_free;
    FBType.tp_dealloc = PyBytes_Type.tp_dealloc;
    if (PyType_Ready(&FBType) < 0) return NULL;
    return PyModule_Create(&mod);
}
